"""Explicit operator recovery for the private, cross-project panel registry."""

from pathlib import Path

import click

from agent_commons.errors import ValidationError
from agent_commons.ui.project_registry import ProjectRegistry

from ._shared import CLIState


@click.group("project")
def project_group() -> None:
    """Inspect panel projects and recover a missing operational-state binding."""


@project_group.command("list")
@click.pass_obj
def list_projects(state: CLIState) -> None:
    """List project IDs, revisions and availability without private paths."""
    state.emit(ProjectRegistry().list_projects(read_only=True))


@project_group.command("recover-state")
@click.argument("project_id")
@click.argument("expected_revision")
@click.option(
    "--state-root",
    "replacement",
    type=click.Path(path_type=Path),
    required=True,
    help="Existing, owned exact state root; never a state base or a new directory.",
)
@click.option("--idempotency-key", required=True)
@click.pass_obj
def recover_state(
    state: CLIState,
    project_id: str,
    expected_revision: str,
    replacement: Path,
    idempotency_key: str,
) -> None:
    """Rebind a missing state root after verifying the registered workspace.

    Stop panels using this project before recovery, then restart the common
    panel. This changes the private registry only; it does not restore lost data.
    """
    if state.read_only:
        raise ValidationError("Project recovery is unavailable in read-only mode.")
    state.emit(
        ProjectRegistry().recover_state(
            project_id,
            expected_revision,
            state_root=replacement,
            idempotency_key=idempotency_key,
        )
    )

"""One authenticated loopback host for several isolated project panels.

The registry keeps private checkout bindings.  This module is the only UI
composition layer allowed to turn one of those bindings into a mounted panel:
there is no selected-project global and a URL is always bound to one immutable
``UIContext`` instance for its lifetime.
"""

from __future__ import annotations

import asyncio
import json
import re
import threading
from collections.abc import Awaitable, Callable
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse, Response

from agent_commons.errors import CommonsError
from agent_commons.ui.context import UIContext
from agent_commons.ui.project_folder_picker import ProjectFolderPicker
from agent_commons.ui.project_operations import ProjectOperations
from agent_commons.ui.project_registry import (
    ProjectRegistry,
    ProjectRegistryRefusal,
    open_project_manager,
)

_PROJECT_ID = re.compile(r"project\.[0-9a-f]{32}\Z")


@dataclass(frozen=True, slots=True)
class ProjectHandle:
    """A fixed context binding owned by this host, never by browser selection."""

    project_id: str
    context: UIContext
    generation: int
    state_binding: str | None
    state_identity: str | None


class ProjectHost:
    """Mount project-local route tables below one opaque browser API base."""

    def __init__(
        self,
        registry: ProjectRegistry,
        operations: ProjectOperations,
        default_context: UIContext,
        *,
        context_factory: Callable[[Path, Path | None], UIContext] | None = None,
        read_only: bool = False,
        max_open_contexts: int = 16,
        max_concurrent_launches: int = 4,
    ) -> None:
        if max_open_contexts < 1 or max_concurrent_launches < 1:
            raise ValueError("project host capacity must be positive")
        self.registry = registry
        self.operations = operations
        self.default_context = default_context
        self._context_factory = context_factory or (
            lambda repo, state: UIContext(repo, state_root=state)
        )
        self.read_only = read_only
        self.max_open_contexts = max_open_contexts
        self._launch_admission = threading.BoundedSemaphore(max_concurrent_launches)
        self._handles: dict[str, ProjectHandle] = {}
        self._children: dict[str, FastAPI] = {}
        self._activation_refusals: dict[str, tuple[str, int, str]] = {}
        self._default_project_id: str | None = None
        self._app: FastAPI | None = None
        self._api_base: str | None = None
        self._generation = 0
        self._port: int | None = None
        self._draining = False
        self._guard = threading.RLock()
        self._folder_picker = ProjectFolderPicker()
        self._picker_guard = threading.Lock()

    @property
    def default_project_id(self) -> str | None:
        return self._default_project_id

    def attach_startup_default(self) -> str | None:
        """Attach the startup checkout only after it has a real workspace.

        A first-run panel intentionally starts before initialization, so an
        unavailable startup directory leaves the registry empty instead of
        making the host constructor fail.
        """

        if self.read_only or self._default_project_id is not None:
            return self._default_project_id
        try:
            # Register the resolved state root, not UIContext's optional
            # input.  A state base or inherited default can resolve to a
            # different root; persisting the input would split receipts and
            # runtime state from the workspace the panel actually reads.
            resolved_state_root = self.default_context.manager().paths.state_root
        except CommonsError:
            # A non-repository or an uninitialized checkout is the explicit
            # first-run state.  It must still serve the bootstrap UI; no
            # registry operation has been attempted in this branch.
            return None
        try:
            result = self.registry.register_existing(
                self.default_context.repo,
                resolved_state_root,
                name=self.default_context.repo.name,
            )
        except ProjectRegistryRefusal:
            # The workspace was already established above, so a registry
            # failure is not bootstrap state and must fail closed.
            raise
        project = result.get("project")
        if not isinstance(project, dict) or not isinstance(project.get("id"), str):
            return None
        project_id = str(project["id"])
        self._default_project_id = project_id
        self._activate(project_id, context=self.default_context)
        return project_id

    def list_projects(self) -> dict[str, Any]:
        self.attach_startup_default()
        payload = dict(self.operations.list_projects())
        payload["default_project_id"] = self._default_project_id
        payload["read_only"] = self.read_only
        return payload

    def create_app(
        self,
        *,
        token: str,
        port: int,
        exchange_code: str | None = None,
        api_base: str | None = None,
    ) -> FastAPI:
        """Create the single outer auth/static host and mount ready projects."""

        from agent_commons.ui.server import _BoundApiRoutes, _error, create_app

        app = create_app(
            self.default_context,
            token=token,
            port=port,
            exchange_code=exchange_code,
            api_base=api_base,
            read_only=self.read_only,
            manage_shutdown=False,
        )
        selected = str(app.state.api_base)
        if not selected:
            raise ValueError("project host requires an opaque outer API base")
        self._app = app
        self._api_base = selected
        self._port = port
        if not self.read_only and self.default_context._session_owner is not None:
            # First run is allowed: an owner defers this lock until setup has
            # created a state root.  Reacquiring an already-held startup lock
            # only refreshes its recorded port.
            self.default_context._session_owner.acquire_panel_lock(port)
            self.default_context._session_owner.start()
        routes = _BoundApiRoutes(app, selected)

        def refusal(exc: Exception) -> Response:
            status = int(getattr(exc, "status", 409))
            code = str(getattr(exc, "code", "project_unavailable"))
            return _error(status, code, str(exc))

        async def project_body(
            request: Request, *, fields: frozenset[str]
        ) -> dict[str, Any] | Response:
            content_length = request.headers.get("content-length")
            if content_length is not None:
                try:
                    if int(content_length) < 0 or int(content_length) > 16 * 1024:
                        return _error(400, "project_invalid", "Project request is invalid.")
                except ValueError:
                    return _error(400, "project_invalid", "Project request is invalid.")
            chunks: list[bytes] = []
            total = 0
            async for chunk in request.stream():
                total += len(chunk)
                if total > 16 * 1024:
                    return _error(400, "project_invalid", "Project request is invalid.")
                chunks.append(chunk)
            raw = b"".join(chunks)
            try:
                value = json.loads(raw)
            except (UnicodeDecodeError, json.JSONDecodeError):
                return _error(400, "project_invalid", "Project request is invalid.")
            if not isinstance(value, dict) or set(value) != fields:
                return _error(400, "project_invalid", "Project request is invalid.")
            return value

        @routes.get("/api/projects")
        async def projects() -> Response:
            try:
                return JSONResponse(await asyncio.to_thread(self.list_projects))
            except ProjectRegistryRefusal as exc:
                return refusal(exc)

        @routes.post("/api/projects/pick-folder")
        async def pick_folder(request: Request) -> Response:
            if self.read_only:
                return _error(403, "read_only", "This host is read-only.")
            body = await project_body(request, fields=frozenset({"purpose"}))
            if isinstance(body, Response):
                return body
            if body["purpose"] not in ("parent", "existing"):
                return _error(400, "project_invalid", "Folder selection purpose is invalid.")

            def choose() -> dict[str, object]:
                if not self._picker_guard.acquire(blocking=False):
                    raise ProjectRegistryRefusal(
                        "project_picker_busy", "A folder chooser is already open.", 409
                    )
                try:
                    return self._folder_picker.pick(body["purpose"])
                finally:
                    self._picker_guard.release()

            try:
                return JSONResponse(
                    await asyncio.to_thread(choose), headers={"Cache-Control": "no-store"}
                )
            except ProjectRegistryRefusal as exc:
                return refusal(exc)

        @routes.post("/api/projects/inspect")
        async def inspect_project(request: Request) -> Response:
            if self.read_only:
                return _error(403, "read_only", "This host is read-only.")
            body = await project_body(request, fields=frozenset({"mode", "path", "name"}))
            if isinstance(body, Response):
                return body
            try:
                return JSONResponse(
                    await asyncio.to_thread(
                        self.operations.inspect,
                        body.get("mode"),
                        body.get("path"),
                        body.get("name"),
                    )
                )
            except ProjectRegistryRefusal as exc:
                return refusal(exc)

        @routes.post("/api/projects")
        async def create_project(request: Request) -> Response:
            if self.read_only:
                return _error(403, "read_only", "This host is read-only.")
            body = await project_body(
                request, fields=frozenset({"inspection_id", "idempotency_key"})
            )
            if isinstance(body, Response):
                return body
            try:
                result = await asyncio.to_thread(
                    self.operations.create,
                    body.get("inspection_id"),
                    body.get("idempotency_key"),
                )
                project = result.get("project")
                if isinstance(project, dict) and isinstance(project.get("id"), str):
                    self._activate(str(project["id"]))
                return JSONResponse(result)
            except ProjectRegistryRefusal as exc:
                return refusal(exc)

        @routes.post("/api/projects/{project_id}/update")
        async def update_project(project_id: str, request: Request) -> Response:
            if self.read_only:
                return _error(403, "read_only", "This host is read-only.")
            if _PROJECT_ID.fullmatch(project_id) is None:
                return _error(404, "project_unknown", "Project was not found.")
            body = await project_body(
                request,
                fields=frozenset({"expected_revision", "name", "archived", "idempotency_key"}),
            )
            if isinstance(body, Response):
                return body
            try:
                return JSONResponse(
                    await asyncio.to_thread(
                        self.operations.update,
                        project_id,
                        body.get("expected_revision"),
                        body.get("name"),
                        body.get("archived"),
                        body.get("idempotency_key"),
                    )
                )
            except ProjectRegistryRefusal as exc:
                return refusal(exc)

        # All project-management routes must precede the subtree dispatcher:
        # `/projects/<id>/update` belongs to this host, never to a project.
        self.attach_startup_default()
        app.mount(f"{selected}/projects", _ProjectDispatcher(self))
        app.router.add_event_handler("shutdown", self.shutdown)
        return app

    def _activate(
        self, project_id: str, *, context: UIContext | None = None
    ) -> ProjectHandle | None:
        """Create and mount one exact binding, bounded without evicting work."""

        if _PROJECT_ID.fullmatch(project_id) is None:
            return None
        with self._guard:
            if self._draining:
                self._activation_refusals[project_id] = (
                    "project_host_draining",
                    409,
                    "This local host is draining existing work.",
                )
                return None
            existing = self._handles.get(project_id)
            if existing is not None:
                return existing
            if len(self._handles) >= self.max_open_contexts:
                self._activation_refusals[project_id] = (
                    "project_capacity",
                    409,
                    "This host has reached its open-project capacity.",
                )
                return None
            try:
                entry = self.registry.project_binding(project_id)
            except ProjectRegistryRefusal:
                return None
            public = entry.public()
            if not public["available"]:
                state = str(public["state"])
                self._activation_refusals[project_id] = (
                    f"project_{state}",
                    409,
                    "This project is unavailable.",
                )
                return None
            state = Path(entry.state_binding) if entry.state_binding is not None else None
            try:
                bound = (
                    context if context is not None else self._context_factory(entry.checkout, state)
                )
                actual_manager = bound.manager()
                registered_manager = open_project_manager(entry.checkout, state, read_only=True)
            except CommonsError:
                self._activation_refusals[project_id] = (
                    "project_unavailable",
                    409,
                    "This project is unavailable.",
                )
                return None
            if (
                not self._same_binding(bound.repo, entry.checkout)
                or actual_manager.workspace_id != entry.workspace_id
                or registered_manager.workspace_id != entry.workspace_id
                or not self._same_binding(
                    actual_manager.paths.state_root, registered_manager.paths.state_root
                )
            ):
                self._activation_refusals[project_id] = (
                    "project_identity_conflict",
                    409,
                    "This project is unavailable.",
                )
                return None
            if not self.read_only and bound._session_owner is not None:
                if self._port is None:
                    return None
                bound._session_owner.acquire_panel_lock(self._port)
                bound._session_owner.start()
            self._generation += 1
            handle = ProjectHandle(
                project_id, bound, self._generation, entry.state_binding, entry.state_identity
            )
            self._handles[project_id] = handle
            self._activation_refusals.pop(project_id, None)
            # The admission token is shared by host-owned contexts only.  The
            # coordinator pins its context and token before it creates a run.
            bound._launch_admission = self._launch_admission
            return handle

    @staticmethod
    def _same_binding(left: Path, right: Path) -> bool:
        try:
            return left.resolve(strict=True) == right.resolve(strict=True)
        except OSError:
            return False

    def project_app(self, handle: ProjectHandle) -> FastAPI:
        """Build one route-only project child after its exact binding is checked."""

        with self._guard:
            existing = self._children.get(handle.project_id)
            if existing is not None:
                return existing
            return self._build_project_app(handle)

    def _build_project_app(self, handle: ProjectHandle) -> FastAPI:
        from agent_commons.ui.server import _error, create_app

        assert self._port is not None
        child = create_app(
            handle.context,
            token="",
            port=self._port,
            api_base="",
            hosted=True,
            read_only=self.read_only,
        )

        @child.middleware("http")
        async def binding_guard(request: Request, call_next: Callable[[Request], Any]) -> Response:
            try:
                entry = self.registry.project_binding(handle.project_id)
                if (
                    not entry.public()["available"]
                    or not self._same_binding(handle.context.repo, entry.checkout)
                    or (entry.state_binding, entry.state_identity)
                    != (handle.state_binding, handle.state_identity)
                ):
                    return _error(409, "project_unavailable", "This project is unavailable.")
            except ProjectRegistryRefusal:
                return _error(404, "project_unknown", "Project was not found.")
            return await call_next(request)

        self._children[handle.project_id] = child
        return child

    def shutdown(self) -> dict[str, Any]:
        """Drain host-owned launch threads without claiming their completion."""

        outcomes: dict[str, Any] = {"projects": {}, "draining": []}
        # Close every project admission gate before draining one of them.  A
        # sequential close left later projects free to create work while an
        # earlier one was joining, which made shutdown non-atomic at host
        # scope.
        with self._guard:
            self._draining = True
            handles = tuple(self._handles.items())
        for _, handle in handles:
            handle.context._launch_coordinator.begin_draining()
            owner = handle.context._session_owner
            if owner is not None:
                owner.begin_draining()
        for project_id, handle in handles:
            owner = handle.context._session_owner
            launch = handle.context._launch_coordinator.shutdown(timeout=None)
            if launch.get("live", 0):
                outcomes["draining"].append(project_id)
            if owner is not None:
                outcomes["projects"][project_id] = owner.shutdown()
        return outcomes


class _ProjectDispatcher:
    """Resolve a project id at request time without a selected-project global."""

    def __init__(self, host: ProjectHost) -> None:
        self._host = host

    async def __call__(
        self,
        scope: dict[str, Any],
        receive: Callable[[], Awaitable[Any]],
        send: Callable[[Any], Awaitable[None]],
    ) -> None:
        raw = str(scope.get("path", ""))
        # Starlette versions differ on whether an ASGI mount hands its child a
        # stripped ``path`` or preserves it and advances ``root_path``.  Accept
        # either representation, while still deriving identity solely from the
        # component immediately below the project mount.
        mount_root = str(scope.get("root_path", ""))
        if mount_root and raw.startswith(mount_root + "/"):
            raw = raw.removeprefix(mount_root)
        project_id, separator, remainder = raw.lstrip("/").partition("/")
        if not separator or _PROJECT_ID.fullmatch(project_id) is None:
            await JSONResponse(
                {"error": {"code": "project_unknown", "message": "Project was not found."}},
                status_code=404,
            )(scope, receive, send)
            return
        handle = await asyncio.to_thread(self._host._activate, project_id)
        if handle is None:
            recorded = self._host._activation_refusals.get(project_id)
            if recorded is not None:
                code, status, message = recorded
                response = JSONResponse(
                    {"error": {"code": code, "message": message}}, status_code=status
                )
                await response(scope, receive, send)
                return
            try:
                self._host.registry.project_binding(project_id)
            except ProjectRegistryRefusal:
                code, status, message = "project_unknown", 404, "Project was not found."
            else:
                code, status, message = (
                    "project_capacity",
                    409,
                    "This host has reached its open-project capacity.",
                )
            await JSONResponse({"error": {"code": code, "message": message}}, status_code=status)(
                scope, receive, send
            )
            return
        child_scope = dict(scope)
        child_scope["path"] = "/" + remainder
        child_scope["raw_path"] = child_scope["path"].encode("utf-8")
        child_scope["root_path"] = str(scope.get("root_path", "")) + "/" + project_id
        await self._host.project_app(handle)(child_scope, receive, send)

"""Private, bounded registry for the projects served by one local host.

The registry is deliberately independent of a project's ledger.  It stores the
operator's choice of checkout and state binding, but publishes only the small
project DTO used by the panel.
"""

from __future__ import annotations

import hashlib
import json
import os
import re
import stat
import subprocess
import time
from collections.abc import Callable, Mapping
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from agent_commons.core.canonical import loads_json_strict
from agent_commons.errors import ConfigurationError, IntegrityError, ValidationError
from agent_commons.storage.atomic import atomic_write_replace
from agent_commons.storage.opstate import OperationalStoragePolicy, exclusive_lock

PROJECT_LIST_SCHEMA = "agent_commons.project_list.v1"
PROJECT_REGISTRY_SCHEMA = "agent_commons.project_registry.v1"
MAX_PROJECTS = 64
MAX_REGISTRY_BYTES = 262_144
_PROJECT_ID = re.compile(r"project\.[0-9a-f]{32}\Z")
_INSPECTION_ID = re.compile(r"inspection\.[0-9a-f]{32}\Z")
_IDENTITY = re.compile(r"[0-9]+:[0-9]+\Z")
_GIT = "/usr/bin/git"
_REGISTRY_POLICY = OperationalStoragePolicy(
    "project registry", True, "project-registry", "resolved", True, True
)


class ProjectRegistryRefusal(ValidationError):
    """A safe, typed refusal for the local project API."""

    def __init__(self, code: str, message: str, status: int = 422) -> None:
        super().__init__(message)
        self.code = code
        self.status = status


def default_project_registry_root() -> Path:
    configured = os.environ.get("XDG_CONFIG_HOME")
    base = (
        Path(configured)
        if configured and Path(configured).is_absolute()
        else Path.home() / ".config"
    )
    return base / "agent-commons" / "projects"


def _canonical(value: Mapping[str, Any]) -> bytes:
    return (
        json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n"
    ).encode()


def _revision(value: Mapping[str, Any]) -> str:
    return "sha256:" + hashlib.sha256(_canonical(value)).hexdigest()


def _safe_text(value: object, *, limit: int = 160) -> str:
    if type(value) is not str or not value.strip() or len(value) > limit:
        raise ProjectRegistryRefusal("project_invalid", "Project details are invalid.")
    if any(ord(character) < 32 for character in value):
        raise ProjectRegistryRefusal("project_invalid", "Project details are invalid.")
    return value.strip()


def _git_identity(checkout: Path) -> str | None:
    try:
        result = subprocess.run(
            [_GIT, "rev-parse", "--git-common-dir"],
            cwd=checkout,
            check=True,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            timeout=5,
            env=_git_environment(),
        )
    except (OSError, subprocess.SubprocessError):
        return None
    value = result.stdout.strip()
    if not value:
        return None
    candidate = Path(value)
    return str((candidate if candidate.is_absolute() else checkout / candidate).resolve())


def _git_environment() -> dict[str, str]:
    """Do not let the panel process redirect Git's repository identity."""
    return {
        key: value
        for key, value in os.environ.items()
        if not key.startswith("GIT_") and key in {"HOME", "PATH", "LANG", "LC_ALL", "TMPDIR"}
    }


def _valid_key(value: object) -> bool:
    return type(value) is str and bool(value) and len(value) <= 160


def _normalized_absolute(value: object) -> bool:
    if not isinstance(value, str) or not Path(value).is_absolute():
        return False
    try:
        return str(Path(value).resolve()) == value
    except OSError:
        return False


def _lexical_absolute(value: object) -> bool:
    """Validate stored intent bytes independently of later filesystem changes."""
    return isinstance(value, str) and Path(value).is_absolute() and os.path.normpath(value) == value


def _create_intent(value: object) -> dict[str, Any] | None:
    if not isinstance(value, dict) or set(value) != {
        "inspection_id",
        "mode",
        "checkout",
        "name",
        "state_binding",
        "initialization_required",
        "anchor_identity",
        "git_identity",
    }:
        return None
    if (
        not isinstance(value["inspection_id"], str)
        or _INSPECTION_ID.fullmatch(value["inspection_id"]) is None
        or value["mode"] not in ("new", "existing")
        or not isinstance(value["checkout"], str)
        or not Path(value["checkout"]).is_absolute()
        or type(value["initialization_required"]) is not bool
        or not isinstance(value["anchor_identity"], str)
        or _IDENTITY.fullmatch(value["anchor_identity"]) is None
        or (
            value["state_binding"] is not None
            and (
                not isinstance(value["state_binding"], str)
                or not Path(value["state_binding"]).is_absolute()
            )
        )
        or (value["git_identity"] is not None and not isinstance(value["git_identity"], str))
    ):
        return None
    try:
        value = dict(value)
        value["name"] = _safe_text(value["name"])
    except ProjectRegistryRefusal:
        return None
    return value


def _normal_intent(value: object) -> bool:
    if not isinstance(value, dict) or set(value) != {
        "checkout",
        "workspace_id",
        "state_binding",
        "name",
    }:
        return False
    if (
        not isinstance(value["checkout"], str)
        or not Path(value["checkout"]).is_absolute()
        or not isinstance(value["workspace_id"], str)
        or not value["workspace_id"].startswith("workspace.")
        or (
            value["state_binding"] is not None
            and (
                not isinstance(value["state_binding"], str)
                or not Path(value["state_binding"]).is_absolute()
            )
        )
    ):
        return False
    try:
        _safe_text(value["name"])
    except ProjectRegistryRefusal:
        return False
    return True


def _directory_identity(path: Path) -> str | None:
    try:
        metadata = path.lstat()
    except OSError:
        return None
    if stat.S_ISLNK(metadata.st_mode) or not stat.S_ISDIR(metadata.st_mode):
        return None
    return f"{metadata.st_dev}:{metadata.st_ino}"


def _default_state_base(checkout: Path) -> Path:
    """Resolve the documented default without consulting inherited UI process env."""
    identity = _git_identity(checkout)
    if identity is None:
        raise ProjectRegistryRefusal("project_not_repository", "Project repository is unavailable.")
    return Path(identity) / "agent-commons-state"


def open_project_manager(
    checkout: Path, state_binding: str | Path | None, *, read_only: bool = False
):
    """Open a project's manager with an explicit binding or its isolated default."""
    from agent_commons.services.manager import CommonsManager

    if state_binding is not None:
        return CommonsManager(
            checkout,
            state_root=state_binding,
            state_source="project-registry",
            read_only=read_only,
        )
    return CommonsManager(
        checkout,
        state_base=_default_state_base(checkout),
        state_source="project-default",
        read_only=read_only,
    )


@dataclass(frozen=True, slots=True)
class RegisteredProject:
    id: str
    workspace_id: str
    name: str
    revision: str
    archived: bool
    checkout: Path
    git_identity: str
    state_binding: str | None
    state_identity: str | None

    def public(self) -> dict[str, Any]:
        state = "ready"
        available = self.checkout.is_dir() and not self.checkout.is_symlink()
        if not available:
            state = "missing"
        elif _git_identity(self.checkout) != self.git_identity:
            state = "identity_conflict"
            available = False
        elif self.state_binding is not None and (
            not _normalized_absolute(self.state_binding)
            or _directory_identity(Path(self.state_binding)) != self.state_identity
        ):
            state = "identity_conflict"
            available = False
        return {
            "id": self.id,
            "workspace_id": self.workspace_id,
            "name": self.name,
            "revision": self.revision,
            "archived": self.archived,
            "available": available,
            "state": state,
        }


class ProjectRegistry:
    """Own a private, CAS-protected registry outside every project workspace."""

    def __init__(
        self,
        root: str | Path | None = None,
        *,
        clock: Callable[[], float] = time.time,
    ) -> None:
        self.root = Path(root) if root is not None else default_project_registry_root()
        self._clock = clock

    @property
    def path(self) -> Path:
        return self.root / "registry.json"

    @property
    def lock_path(self) -> Path:
        return self.root / "registry.lock"

    def _ensure_root(self) -> None:
        # Create each missing directory ourselves so a newly introduced symlink
        # cannot be followed by mkdir/chmod.  The registry root is operator data.
        current = self.root
        missing: list[Path] = []
        while not current.exists():
            missing.append(current)
            current = current.parent
        if current.is_symlink() or not current.is_dir():
            raise ProjectRegistryRefusal(
                "project_registry_unavailable", "Project registry is unavailable.", 409
            )
        for directory in reversed(missing):
            directory.mkdir(mode=0o700)
            if directory.is_symlink() or not directory.is_dir():
                raise ProjectRegistryRefusal(
                    "project_registry_unavailable", "Project registry is unavailable.", 409
                )
        try:
            metadata = self.root.lstat()
            if not stat.S_ISDIR(metadata.st_mode) or stat.S_ISLNK(metadata.st_mode):
                raise OSError("unsafe root")
            if hasattr(os, "getuid") and metadata.st_uid != os.getuid():
                raise OSError("foreign owner")
            os.chmod(self.root, 0o700, follow_symlinks=False)
        except OSError as exc:
            raise ProjectRegistryRefusal(
                "project_registry_unavailable", "Project registry is unavailable.", 409
            ) from exc

    def _empty(self) -> dict[str, Any]:
        body: dict[str, Any] = {"schema": PROJECT_REGISTRY_SCHEMA, "projects": [], "receipts": {}}
        body["revision"] = _revision(body)
        return body

    def _load(self, *, read_only: bool = False) -> dict[str, Any]:
        if not read_only:
            self._ensure_root()
        elif self.root.is_symlink():
            raise ProjectRegistryRefusal(
                "project_registry_unavailable", "Project registry is unavailable.", 409
            )
        if not self.path.exists():
            return self._empty()
        if self.path.is_symlink():
            raise ProjectRegistryRefusal(
                "project_registry_unavailable", "Project registry is unavailable.", 409
            )
        descriptor = -1
        try:
            before = self.path.lstat()
            descriptor = os.open(self.path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
            metadata = os.fstat(descriptor)
            if (
                not stat.S_ISREG(metadata.st_mode)
                or metadata.st_uid != os.getuid()
                or metadata.st_size > MAX_REGISTRY_BYTES
            ):
                raise OSError("unsafe registry")
            with os.fdopen(descriptor, "rb", closefd=True) as handle:
                raw = handle.read(MAX_REGISTRY_BYTES + 1)
            descriptor = -1
            after = self.path.lstat()
            if (before.st_dev, before.st_ino) != (after.st_dev, after.st_ino) or len(
                raw
            ) > MAX_REGISTRY_BYTES:
                raise OSError("registry changed while read")
            value = loads_json_strict(raw)
        except (OSError, ValidationError) as exc:
            raise ProjectRegistryRefusal(
                "project_registry_unavailable", "Project registry is unavailable.", 409
            ) from exc
        finally:
            if descriptor >= 0:
                os.close(descriptor)
        self._validate(value)
        return value

    def _validate(self, value: object) -> None:
        if not isinstance(value, dict) or set(value) != {
            "schema",
            "revision",
            "projects",
            "receipts",
        }:
            raise ProjectRegistryRefusal(
                "project_registry_unavailable", "Project registry is unavailable.", 409
            )
        if (
            value["schema"] != PROJECT_REGISTRY_SCHEMA
            or not isinstance(value["projects"], list)
            or not isinstance(value["receipts"], dict)
        ):
            raise ProjectRegistryRefusal(
                "project_registry_unavailable", "Project registry is unavailable.", 409
            )
        if len(value["projects"]) > MAX_PROJECTS or len(value["receipts"]) > MAX_PROJECTS * 4:
            raise ProjectRegistryRefusal(
                "project_registry_unavailable", "Project registry is unavailable.", 409
            )
        expected = dict(value)
        revision = expected.pop("revision")
        if not isinstance(revision, str) or revision != _revision(expected):
            raise ProjectRegistryRefusal(
                "project_registry_unavailable", "Project registry is unavailable.", 409
            )
        ids: set[str] = set()
        workspace_ids: set[str] = set()
        for record in value["projects"]:
            self._record(record)
            if record["id"] in ids or record["workspace_id"] in workspace_ids:
                raise ProjectRegistryRefusal(
                    "project_registry_unavailable", "Project registry is unavailable.", 409
                )
            ids.add(record["id"])
            workspace_ids.add(record["workspace_id"])
        for key, receipt in value["receipts"].items():
            if not _valid_key(key) or not self._valid_receipt(receipt, ids):
                raise ProjectRegistryRefusal(
                    "project_registry_unavailable", "Project registry is unavailable.", 409
                )

    @staticmethod
    def _valid_receipt(value: object, project_ids: set[str]) -> bool:
        if not isinstance(value, dict):
            return False
        if set(value) == {"intent", "project_id"}:
            intent = value["intent"]
            update = (
                isinstance(intent, dict)
                and set(intent) == {"project_id", "expected_revision", "name", "archived"}
                and intent.get("project_id") in project_ids
                and isinstance(intent.get("expected_revision"), str)
                and (
                    intent.get("name") is None
                    or _normal_intent(
                        {
                            "checkout": "/",
                            "workspace_id": "workspace.x",
                            "state_binding": None,
                            "name": intent.get("name"),
                        }
                    )
                )
                and (intent.get("archived") is None or type(intent.get("archived")) is bool)
            )
            recovery = (
                isinstance(intent, dict)
                and set(intent) == {"project_id", "expected_revision", "recover_state"}
                and intent.get("project_id") in project_ids
                and isinstance(intent.get("expected_revision"), str)
                and _lexical_absolute(intent.get("recover_state"))
            )
            return (_normal_intent(intent) or update or recovery) and value[
                "project_id"
            ] in project_ids
        expected = {"create_intent", "project_id", "milestone", "target_identity"}
        if set(value) != expected or _create_intent(value["create_intent"]) is None:
            return False
        if value["project_id"] is not None and value["project_id"] not in project_ids:
            return False
        if value["milestone"] not in {
            "reserved",
            "directory_created",
            "git_initialized",
            "commons_initialized",
            "published",
        }:
            return False
        if value["milestone"] == "reserved":
            return value["target_identity"] is None and value["project_id"] is None
        if (
            not isinstance(value["target_identity"], str)
            or _IDENTITY.fullmatch(value["target_identity"]) is None
        ):
            return False
        return (value["milestone"] == "published") == (value["project_id"] is not None)

    def _record(self, value: object) -> RegisteredProject:
        if not isinstance(value, dict) or set(value) != {
            "id",
            "workspace_id",
            "name",
            "revision",
            "archived",
            "checkout",
            "git_identity",
            "state_binding",
            "state_identity",
        }:
            raise ProjectRegistryRefusal(
                "project_registry_unavailable", "Project registry is unavailable.", 409
            )
        if not isinstance(value["id"], str) or _PROJECT_ID.fullmatch(value["id"]) is None:
            raise ProjectRegistryRefusal(
                "project_registry_unavailable", "Project registry is unavailable.", 409
            )
        if not isinstance(value["workspace_id"], str) or not value["workspace_id"].startswith(
            "workspace."
        ):
            raise ProjectRegistryRefusal(
                "project_registry_unavailable", "Project registry is unavailable.", 409
            )
        if (
            not isinstance(value["name"], str)
            or not isinstance(value["revision"], str)
            or not isinstance(value["archived"], bool)
        ):
            raise ProjectRegistryRefusal(
                "project_registry_unavailable", "Project registry is unavailable.", 409
            )
        if (
            not isinstance(value["checkout"], str)
            or not Path(value["checkout"]).is_absolute()
            or not isinstance(value["git_identity"], str)
        ):
            raise ProjectRegistryRefusal(
                "project_registry_unavailable", "Project registry is unavailable.", 409
            )
        if value["state_binding"] is not None and (
            not isinstance(value["state_binding"], str)
            or not Path(value["state_binding"]).is_absolute()
        ):
            raise ProjectRegistryRefusal(
                "project_registry_unavailable", "Project registry is unavailable.", 409
            )
        if value["state_binding"] is None:
            if value["state_identity"] is not None:
                raise ProjectRegistryRefusal(
                    "project_registry_unavailable", "Project registry is unavailable.", 409
                )
        elif not isinstance(value["state_identity"], str):
            raise ProjectRegistryRefusal(
                "project_registry_unavailable", "Project registry is unavailable.", 409
            )
        body = dict(value)
        revision = body.pop("revision")
        if revision != _revision(body):
            raise ProjectRegistryRefusal(
                "project_registry_unavailable", "Project registry is unavailable.", 409
            )
        return RegisteredProject(
            value["id"],
            value["workspace_id"],
            value["name"],
            value["revision"],
            value["archived"],
            Path(value["checkout"]),
            value["git_identity"],
            value["state_binding"],
            value["state_identity"],
        )

    def _save(self, value: dict[str, Any]) -> None:
        body = dict(value)
        if (
            not isinstance(body.get("projects"), list)
            or not isinstance(body.get("receipts"), dict)
            or len(body["projects"]) > MAX_PROJECTS
            or len(body["receipts"]) > MAX_PROJECTS * 4
        ):
            raise ProjectRegistryRefusal(
                "project_registry_full", "Project registry has reached its storage limit.", 409
            )
        body.pop("revision", None)
        body["revision"] = _revision(body)
        if len(_canonical(body)) > MAX_REGISTRY_BYTES:
            raise ProjectRegistryRefusal(
                "project_registry_full", "Project registry has reached its storage limit.", 409
            )
        value.clear()
        value.update(body)
        atomic_write_replace(self.path, _canonical(value), mode=0o600)

    def _entries(self, document: Mapping[str, Any]) -> list[RegisteredProject]:
        return [self._record(item) for item in document["projects"]]

    def list_projects(self, *, read_only: bool = False) -> dict[str, Any]:
        if read_only:
            document = self._load(read_only=True)
            return {
                "schema": PROJECT_LIST_SCHEMA,
                "revision": document["revision"],
                "projects": [entry.public() for entry in self._entries(document)],
            }
        self._ensure_root()
        with exclusive_lock(self.lock_path, policy=_REGISTRY_POLICY):
            document = self._load()
            return {
                "schema": PROJECT_LIST_SCHEMA,
                "revision": document["revision"],
                "projects": [entry.public() for entry in self._entries(document)],
            }

    def project_binding(self, project_id: str) -> RegisteredProject:
        """Return the private binding for the trusted local host only."""
        return self.get(project_id)

    def is_registered_checkout(self, checkout: Path) -> bool:
        """Private idempotency seam; never expose checkout paths to clients."""
        self._ensure_root()
        with exclusive_lock(self.lock_path, policy=_REGISTRY_POLICY):
            return any(entry.checkout == checkout for entry in self._entries(self._load()))

    def overlaps_registered_checkout(self, path: Path) -> bool:
        """Private placement guard for another project checkout's entire tree."""
        self._ensure_root()
        with exclusive_lock(self.lock_path, policy=_REGISTRY_POLICY):
            return any(
                path == entry.checkout
                or entry.checkout in path.parents
                or path in entry.checkout.parents
                for entry in self._entries(self._load())
            )

    def get(self, project_id: str) -> RegisteredProject:
        if not isinstance(project_id, str) or _PROJECT_ID.fullmatch(project_id) is None:
            raise ProjectRegistryRefusal("project_unknown", "Project was not found.", 404)
        self._ensure_root()
        with exclusive_lock(self.lock_path, policy=_REGISTRY_POLICY):
            for entry in self._entries(self._load()):
                if entry.id == project_id:
                    return entry
        raise ProjectRegistryRefusal("project_unknown", "Project was not found.", 404)

    def register_existing(
        self, repo: str | Path, state_binding: str | Path | None = None, *, name: str | None = None
    ) -> dict[str, Any]:
        """Trusted startup attachment.  It never initializes a checkout."""
        checkout = Path(repo).expanduser().resolve(strict=True)
        if checkout.is_symlink() or not checkout.is_dir() or _git_identity(checkout) is None:
            raise ProjectRegistryRefusal(
                "project_not_repository", "Project repository is unavailable."
            )
        try:
            manager = open_project_manager(checkout, state_binding, read_only=True)
        except (ConfigurationError, IntegrityError) as exc:
            raise ProjectRegistryRefusal(
                "project_unavailable", "Project is unavailable.", 409
            ) from exc
        return self.register(
            checkout=checkout,
            workspace_id=manager.workspace_id,
            state_binding=manager.paths.state_root,
            name=name or checkout.name,
            # Startup attachment is an assertion of this exact binding, not a
            # permanent operation key for every state directory ever selected.
            idempotency_key="startup:v2:"
            + hashlib.sha256(
                _canonical(
                    {
                        "checkout": str(checkout),
                        "state_binding": str(manager.paths.state_root),
                        "workspace_id": manager.workspace_id,
                        "name": name or checkout.name,
                    }
                )
            ).hexdigest(),
        )

    def recover_state(
        self,
        project_id: str,
        expected_revision: str,
        *,
        state_root: Path,
        idempotency_key: str,
    ) -> dict[str, Any]:
        """Explicitly replace a missing binding with an already-owned exact root.

        This does not migrate or recreate operational data. The previous root
        must be absent, and the replacement must already belong to the same
        workspace and checkout. The old registration receipts remain intact.
        """
        state = str(state_root.expanduser().absolute())
        if (
            not _valid_key(idempotency_key)
            or not isinstance(expected_revision, str)
            or not _normalized_absolute(state)
        ):
            raise ProjectRegistryRefusal("project_invalid", "Project recovery is invalid.")
        intent = {
            "project_id": project_id,
            "expected_revision": expected_revision,
            "recover_state": state,
        }
        self._ensure_root()
        with exclusive_lock(self.lock_path, policy=_REGISTRY_POLICY):
            document = self._load()
            receipt = document["receipts"].get(idempotency_key)
            if receipt is not None and receipt != {"intent": intent, "project_id": project_id}:
                raise ProjectRegistryRefusal(
                    "project_idempotency_mismatch", "Project recovery input changed.", 409
                )
            for index, entry in enumerate(self._entries(document)):
                if entry.id != project_id:
                    continue
                if receipt is None and entry.revision != expected_revision:
                    raise ProjectRegistryRefusal(
                        "project_stale", "Project changed; refresh and try again.", 409
                    )
                if (
                    _git_identity(entry.checkout) != entry.git_identity
                    or entry.checkout.is_symlink()
                ):
                    raise ProjectRegistryRefusal(
                        "project_identity_conflict", "Project repository identity changed.", 409
                    )
                if receipt is None:
                    if entry.state_binding is None:
                        raise ProjectRegistryRefusal(
                            "project_state_not_missing",
                            "Only a missing state root can be recovered.",
                            409,
                        )
                    try:
                        Path(entry.state_binding).lstat()
                    except FileNotFoundError:
                        pass
                    else:
                        raise ProjectRegistryRefusal(
                            "project_state_not_missing",
                            "The previous state root still exists.",
                            409,
                        )
                try:
                    before_identity = _directory_identity(Path(state))
                    manager = open_project_manager(entry.checkout, state, read_only=True)
                    state_identity = _directory_identity(Path(state))
                    ownership = manager.paths.ownership_report()
                    if (
                        state_identity is None
                        or manager.paths.state_root != Path(state)
                        or state_identity != before_identity
                        or ownership["status"] not in {"owned", "legacy-owned"}
                        or ownership["match"] is not True
                        or manager.workspace_id != entry.workspace_id
                        or any(issue.severity == "error" for issue in manager.snapshot().issues)
                    ):
                        raise ValueError("binding mismatch")
                except (ConfigurationError, IntegrityError, OSError, ValueError) as exc:
                    raise ProjectRegistryRefusal(
                        "project_recovery_unverified",
                        "The replacement must be an existing state root owned by this workspace.",
                        409,
                    ) from exc
                if _directory_identity(Path(state)) != state_identity:
                    raise ProjectRegistryRefusal(
                        "project_state_binding_conflict",
                        "Replacement state changed during recovery.",
                        409,
                    )
                if receipt is not None:
                    if entry.state_binding != state or entry.state_identity != state_identity:
                        raise ProjectRegistryRefusal(
                            "project_state_binding_conflict",
                            "Recovered project binding changed.",
                            409,
                        )
                    return {"project": entry.public(), "revision": document["revision"]}
                body = dict(document["projects"][index])
                body.pop("revision")
                body.update(state_binding=state, state_identity=state_identity)
                body["revision"] = _revision(body)
                document["projects"][index] = body
                document["receipts"][idempotency_key] = {"intent": intent, "project_id": project_id}
                self._save(document)
                return {"project": self._record(body).public(), "revision": document["revision"]}
        raise ProjectRegistryRefusal("project_unknown", "Project was not found.", 404)

    def register(
        self,
        *,
        checkout: Path,
        workspace_id: str,
        state_binding: str | Path | None,
        name: str,
        idempotency_key: str,
        create_intent: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        label = _safe_text(name)
        if not _valid_key(idempotency_key):
            raise ProjectRegistryRefusal("project_invalid", "Project request is invalid.")
        identity = _git_identity(checkout)
        if identity is None:
            raise ProjectRegistryRefusal(
                "project_not_repository", "Project repository is unavailable."
            )
        normalized = str(checkout.resolve())
        state = (
            str(Path(state_binding).expanduser().resolve()) if state_binding is not None else None
        )
        state_identity = _directory_identity(Path(state)) if state is not None else None
        if state is not None and state_identity is None:
            raise ProjectRegistryRefusal(
                "project_unavailable", "Project state is unavailable.", 409
            )
        intent = {
            "checkout": normalized,
            "workspace_id": workspace_id,
            "state_binding": state,
            "name": label,
        }
        self._ensure_root()
        with exclusive_lock(self.lock_path, policy=_REGISTRY_POLICY):
            document = self._load()
            receipt = document["receipts"].get(idempotency_key)
            if receipt is not None:
                reserved = (
                    create_intent is not None
                    and isinstance(receipt, dict)
                    and "create_intent" in receipt
                    and receipt.get("create_intent") == create_intent
                )
                ordinary = isinstance(receipt, dict) and receipt.get("intent") == intent
                if not reserved and not ordinary:
                    raise ProjectRegistryRefusal(
                        "project_idempotency_mismatch",
                        "Project request key was reused for different input.",
                        409,
                    )
                project_id = receipt.get("project_id")
                if isinstance(project_id, str):
                    for entry in self._entries(document):
                        if entry.id == project_id:
                            if (
                                entry.checkout != checkout
                                or entry.workspace_id != workspace_id
                                or entry.git_identity != identity
                                or entry.state_binding != state
                                or entry.state_identity != state_identity
                            ):
                                raise ProjectRegistryRefusal(
                                    "project_state_binding_conflict",
                                    "Project state binding changed.",
                                    409,
                                )
                            return {"project": entry.public(), "revision": document["revision"]}
                    raise ProjectRegistryRefusal(
                        "project_registry_unavailable", "Project registry is unavailable.", 409
                    )
            entries = self._entries(document)
            for entry in entries:
                if entry.workspace_id == workspace_id:
                    if (
                        entry.checkout == checkout
                        and entry.git_identity == identity
                        and entry.state_binding == state
                        and entry.state_identity == state_identity
                    ):
                        result = {"project": entry.public(), "revision": document["revision"]}
                        document["receipts"][idempotency_key] = self._receipt(
                            intent, entry.id, create_intent, _directory_identity(checkout)
                        )
                        self._save(document)
                        return result
                    code = (
                        "project_state_binding_conflict"
                        if entry.checkout == checkout and entry.git_identity == identity
                        else "project_workspace_registered"
                    )
                    raise ProjectRegistryRefusal(
                        code,
                        "This workspace is already registered with a different binding.",
                        409,
                    )
            if len(entries) >= MAX_PROJECTS:
                raise ProjectRegistryRefusal(
                    "project_limit_reached", "The project limit has been reached.", 409
                )
            body = {
                "id": "project." + os.urandom(16).hex(),
                "workspace_id": workspace_id,
                "name": label,
                "archived": False,
                "checkout": normalized,
                "git_identity": identity,
                "state_binding": state,
                "state_identity": state_identity,
            }
            body["revision"] = _revision(body)
            document["projects"].append(body)
            document["receipts"][idempotency_key] = self._receipt(
                intent, body["id"], create_intent, _directory_identity(checkout)
            )
            self._save(document)
            return {"project": self._record(body).public(), "revision": document["revision"]}

    @staticmethod
    def _receipt(
        intent: Mapping[str, Any],
        project_id: str | None,
        create_intent: Mapping[str, Any] | None,
        target_identity: str | None,
    ) -> dict[str, Any]:
        if create_intent is None:
            return {"intent": dict(intent), "project_id": project_id}
        assert project_id is not None and target_identity is not None
        return {
            "create_intent": dict(create_intent),
            "project_id": project_id,
            "milestone": "published",
            "target_identity": target_identity,
        }

    def reserve_create(
        self, idempotency_key: str, intent: Mapping[str, Any]
    ) -> dict[str, Any] | None:
        """Durably bind a request key before checkout side effects begin."""
        if not _valid_key(idempotency_key):
            raise ProjectRegistryRefusal("project_invalid", "Project request is invalid.")
        self._ensure_root()
        frozen = _create_intent(intent)
        if frozen is None:
            raise ProjectRegistryRefusal("project_invalid", "Project request is invalid.")
        with exclusive_lock(self.lock_path, policy=_REGISTRY_POLICY):
            document = self._load()
            receipt = document["receipts"].get(idempotency_key)
            if receipt is not None:
                if not isinstance(receipt, dict) or receipt.get("create_intent") != frozen:
                    raise ProjectRegistryRefusal(
                        "project_idempotency_mismatch",
                        "Project request key was reused for different input.",
                        409,
                    )
                project_id = receipt.get("project_id")
                if isinstance(project_id, str):
                    for entry in self._entries(document):
                        if entry.id == project_id:
                            return {"project": entry.public(), "revision": document["revision"]}
                    raise ProjectRegistryRefusal(
                        "project_registry_unavailable", "Project registry is unavailable.", 409
                    )
                return None
            document["receipts"][idempotency_key] = {
                "create_intent": frozen,
                "project_id": None,
                "milestone": "reserved",
                "target_identity": None,
            }
            self._save(document)
            return None

    def create_progress(self, idempotency_key: str, intent: Mapping[str, Any]) -> dict[str, Any]:
        frozen = _create_intent(intent)
        if frozen is None:
            raise ProjectRegistryRefusal("project_invalid", "Project request is invalid.")
        self._ensure_root()
        with exclusive_lock(self.lock_path, policy=_REGISTRY_POLICY):
            receipt = self._load()["receipts"].get(idempotency_key)
            if not isinstance(receipt, dict) or receipt.get("create_intent") != frozen:
                raise ProjectRegistryRefusal(
                    "project_idempotency_mismatch",
                    "Project request key was reused for different input.",
                    409,
                )
            return dict(receipt)

    def advance_create(
        self, idempotency_key: str, intent: Mapping[str, Any], milestone: str, target: Path
    ) -> None:
        frozen = _create_intent(intent)
        identity = _directory_identity(target)
        if (
            frozen is None
            or identity is None
            or milestone not in {"directory_created", "git_initialized", "commons_initialized"}
        ):
            raise ProjectRegistryRefusal("project_invalid", "Project request is invalid.")
        self._ensure_root()
        with exclusive_lock(self.lock_path, policy=_REGISTRY_POLICY):
            document = self._load()
            receipt = document["receipts"].get(idempotency_key)
            if not isinstance(receipt, dict) or receipt.get("create_intent") != frozen:
                raise ProjectRegistryRefusal(
                    "project_idempotency_mismatch",
                    "Project request key was reused for different input.",
                    409,
                )
            if receipt.get("project_id") is not None:
                return
            receipt["milestone"] = milestone
            receipt["target_identity"] = identity
            self._save(document)

    def recover_create(self, inspection_id: str, idempotency_key: str) -> dict[str, Any] | None:
        """Recover a reserved create after a host restart lost inspection memory."""
        self._ensure_root()
        with exclusive_lock(self.lock_path, policy=_REGISTRY_POLICY):
            document = self._load()
            receipt = document["receipts"].get(idempotency_key)
            if not isinstance(receipt, dict):
                return None
            intent = receipt.get("create_intent")
            if not isinstance(intent, dict) or intent.get("inspection_id") != inspection_id:
                raise ProjectRegistryRefusal(
                    "project_idempotency_mismatch",
                    "Project request key was reused for different input.",
                    409,
                )
            project_id = receipt.get("project_id")
            if isinstance(project_id, str):
                for entry in self._entries(document):
                    if entry.id == project_id:
                        return {"project": entry.public(), "revision": document["revision"]}
                raise ProjectRegistryRefusal(
                    "project_registry_unavailable", "Project registry is unavailable.", 409
                )
            return dict(intent)

    def update(
        self,
        project_id: str,
        expected_revision: str,
        *,
        name: str | None = None,
        archived: bool | None = None,
        idempotency_key: str,
    ) -> dict[str, Any]:
        if not isinstance(expected_revision, str) or not _valid_key(idempotency_key):
            raise ProjectRegistryRefusal("project_invalid", "Project request is invalid.")
        if name is None and archived is None:
            raise ProjectRegistryRefusal("project_invalid", "Project update is empty.")
        if name is not None:
            name = _safe_text(name)
        if archived is not None and type(archived) is not bool:
            raise ProjectRegistryRefusal("project_invalid", "Project update is invalid.")
        intent = {
            "project_id": project_id,
            "expected_revision": expected_revision,
            "name": name,
            "archived": archived,
        }
        self._ensure_root()
        with exclusive_lock(self.lock_path, policy=_REGISTRY_POLICY):
            document = self._load()
            receipt = document["receipts"].get(idempotency_key)
            if receipt is not None:
                if (
                    not isinstance(receipt, dict)
                    or receipt.get("intent") != intent
                    or not isinstance(receipt.get("project_id"), str)
                ):
                    raise ProjectRegistryRefusal(
                        "project_idempotency_mismatch",
                        "Project request key was reused for different input.",
                        409,
                    )
                for entry in self._entries(document):
                    if entry.id == receipt["project_id"]:
                        return {"project": entry.public(), "revision": document["revision"]}
                raise ProjectRegistryRefusal(
                    "project_registry_unavailable", "Project registry is unavailable.", 409
                )
            for index, entry in enumerate(self._entries(document)):
                if entry.id != project_id:
                    continue
                if entry.revision != expected_revision:
                    raise ProjectRegistryRefusal(
                        "project_stale", "Project changed; refresh and try again.", 409
                    )
                body = {
                    "id": entry.id,
                    "workspace_id": entry.workspace_id,
                    "name": name if name is not None else entry.name,
                    "archived": archived if archived is not None else entry.archived,
                    "checkout": str(entry.checkout),
                    "git_identity": entry.git_identity,
                    "state_binding": entry.state_binding,
                    "state_identity": entry.state_identity,
                }
                body["revision"] = _revision(body)
                document["projects"][index] = body
                document["receipts"][idempotency_key] = {"intent": intent, "project_id": entry.id}
                self._save(document)
                return {"project": self._record(body).public(), "revision": document["revision"]}
        raise ProjectRegistryRefusal("project_unknown", "Project was not found.", 404)
